import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_internal_token(req):
    """Verify the request came from an authorized internal service."""
    token = req.headers.get('X-Internal-Auth')
    if not token:
        return False
    expected = hmac.new(SECRET_KEY.encode(), b'internal-service', hashlib.sha256).hexdigest()
    return hmac.compare_digest(token, expected)

def sanitize_sort_field(field):
    """Allow only known sort fields to prevent injection in ORDER BY."""
    allowed = ['username', 'email', 'created_at', 'last_login']
    if field in allowed:
        return field
    return 'created_at'

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering and sorting."""
    query_param = request.args.get('q', '')
    department = request.args.get('dept', '')
    sort_by = sanitize_sort_field(request.args.get('sort', 'created_at'))
    page = request.args.get('page', '1')

    # Build the search query
    base_query = "SELECT id, username, email, department, created_at FROM users WHERE 1=1"
    params = []

    if query_param:
        base_query += " AND (username LIKE ? OR email LIKE ?)"
        params.extend(['%' + query_param + '%', '%' + query_param + '%'])

    if department:
        base_query += " AND department = '" + department + "'"

    base_query += f" ORDER BY {sort_by} LIMIT 50 OFFSET " + str((int(page) - 1) * 50)

    db = get_db()
    try:
        results = db.execute(base_query, params).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, email, department, created_at FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/admin/users', methods=['GET'])
def admin_list_users():
    """Admin endpoint - lists all users including sensitive fields."""
    if not verify_internal_token(request):
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    results = db.execute('SELECT * FROM users').fetchall()
    return jsonify([dict(row) for row in results])

@app.route('/api/users/export', methods=['POST'])
def export_users():
    """Export user data based on filter criteria."""
    data = request.get_json(force=True)
    filter_field = data.get('field', 'department')
    filter_value = data.get('value', '')

    allowed_fields = ['department', 'role', 'status']
    if filter_field not in allowed_fields:
        return jsonify({'error': 'Invalid filter field'}), 400

    query = f"SELECT username, email, department FROM users WHERE {filter_field} = ?"
    db = get_db()
    results = db.execute(query, (filter_value,)).fetchall()
    return jsonify({'count': len(results), 'data': [dict(row) for row in results]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
